#include <stdio.h>

static int lower_bound(const int a[], int n, int target)
{
    int low = 0;
    int high = n;
    while (low < high) {
        int mid = low + (high - low) / 2;
        if (a[mid] < target) {
            low = mid + 1;
        } else {
            high = mid;
        }
    }
    return low;
}

int main(void)
{
    int a[] = {1, 3, 3, 5};
    printf("%d\n", lower_bound(a, 4, 3));
    return 0;
}
